def calc(expr: str) -> int | str:
    class _EvalError(Exception):
        pass

    n = len(expr)
    pos = 0

    def parse_atom() -> int:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1
        if expr[pos] == "(":
            pos += 1
            val = parse_expr()
            while pos < n and expr[pos].isspace():
                pos += 1
            pos += 1
            return val
        start = pos
        while pos < n and "0" <= expr[pos] <= "9":
            pos += 1
        s = expr[start:pos]
        if len(s) <= 4000:
            return int(s)
        val = 0
        for i in range(0, len(s), 4000):
            chunk = s[i : i + 4000]
            val = val * (10 ** len(chunk)) + int(chunk)
        return val

    def parse_unary() -> int:
        nonlocal pos
        items: list[tuple[bool, int]] = []
        while True:
            neg = False
            while pos < n:
                ch = expr[pos]
                if ch.isspace():
                    pos += 1
                elif ch == "-":
                    neg = not neg
                    pos += 1
                else:
                    break
            base = parse_atom()
            items.append((neg, base))
            while pos < n and expr[pos].isspace():
                pos += 1
            if pos < n and expr[pos] == "^":
                pos += 1
            else:
                break

        neg, val = items[-1]
        if neg:
            val = -val
        for i in range(len(items) - 2, -1, -1):
            neg, base = items[i]
            if val < 0:
                raise _EvalError
            if val == 0:
                val = 1
            elif base == 0:
                val = 0
            elif base == 1:
                val = 1
            elif base == -1:
                val = -1 if (val & 1) else 1
            else:
                val = base**val
            if neg:
                val = -val
        return val

    def parse_term() -> int:
        nonlocal pos
        val = parse_unary()
        while True:
            while pos < n and expr[pos].isspace():
                pos += 1
            if pos >= n:
                break
            op = expr[pos]
            if op == "*":
                pos += 1
                val *= parse_unary()
            elif op == "/":
                pos += 1
                rhs = parse_unary()
                if rhs == 0:
                    raise _EvalError
                q = abs(val) // abs(rhs)
                val = -q if (val < 0) != (rhs < 0) else q
            elif op == "%":
                pos += 1
                rhs = parse_unary()
                if rhs == 0:
                    raise _EvalError
                r = abs(val) % abs(rhs)
                val = -r if val < 0 else r
            else:
                break
        return val

    def parse_expr() -> int:
        nonlocal pos
        val = parse_term()
        while True:
            while pos < n and expr[pos].isspace():
                pos += 1
            if pos >= n:
                break
            op = expr[pos]
            if op == "+":
                pos += 1
                val += parse_term()
            elif op == "-":
                pos += 1
                val -= parse_term()
            else:
                break
        return val

    try:
        return parse_expr()
    except _EvalError:
        return "error"
